INSERT INTO `sys_user` (`id`, `nickname`, `realname`, `gender`, `avatar`, `phone`, `email`, `idtype`, `idcode`, `motto`, `birthDate`, `status`, `education`, `location`, `biography`, `creator`, `updater`, `create_time`, `update_time`) VALUES
	(3, '孔子', '孔丘', 1, NULL, '', 'kongzi@ruilink.top', NULL, NULL, '己所不欲，勿施于人', NULL, 1, NULL, '370800', '孔子（公元前 551 年 9 月 28 日—前 479 年 4 月 11 日），名丘，字仲尼，春秋时期鲁国陬邑（今山东省曲阜市）人，中国古代思想家、政治家、教育家，儒家学派创始人。', 2, 2, '2026-10-08 19:35:09', '2026-10-08 19:35:09'),
	(4, '孟子', '孟轲', 1, NULL, '', 'mengzi@ruilink.top', NULL, NULL, '民为贵，社稷次之，君为轻', NULL, 1, NULL, '370800', '孟子（公元前372年-公元前289年），姬姓，孟氏，名轲，字子舆（待考，一说字子车、子居），与孔子并称“孔孟”，战国时期邹国（今山东邹城）人。是儒学集大成者、儒家学派的代表人物，中国古代思想家、哲学家、政治家、教育家。', 2, 2, '2026-10-08 19:36:53', '2026-10-08 19:36:53'),
	(5, '太白', '李白', 1, NULL, '', 'libai@ruilink.top', NULL, NULL, '天生我材必有用，千金散尽还复来', NULL, 1, NULL, '510700', '李白（701 年—762 年）是‌中国唐代伟大的浪漫主义诗人‌，字太白，号青莲居士，被后世尊称为“诗仙”。他的诗歌豪放飘逸、想象丰富，代表了盛唐气象，是中国古典文学的高峰之一。', 2, 2, '2026-10-08 19:40:12', '2026-10-08 19:40:12'),
	(6, '子瞻', '苏轼', 1, NULL, '', 'sushi@ruilink.top', NULL, NULL, '竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生。', NULL, 1, NULL, '511400', '苏轼（1037年—1101年），字子瞻，号东坡居士，世称苏东坡。眉州眉山（今四川省眉山市）人，北宋文学家，书法家、画家。', 2, 2, '2026-10-08 19:42:38', '2026-10-08 19:42:38');
